import struct
import hashlib
import hmac
import os
import time
from typing import Optional, Tuple, Dict, List

class SecureBufferPool:
    """Memory pool for handling protocol messages with zero-copy semantics."""

    POOL_SIZE = 4096
    SLOT_SIZE = 64
    MAX_SLOTS = POOL_SIZE // SLOT_SIZE  # 64 slots

    def __init__(self):
        self._pool = bytearray(self.POOL_SIZE)
        self._slot_owners: Dict[int, str] = {}
        self._hmac_key = os.urandom(32)

    def allocate_slot(self, owner_id: str) -> Optional[int]:
        """Allocate a slot in the buffer pool."""
        for i in range(self.MAX_SLOTS):
            if i not in self._slot_owners:
                self._slot_owners[i] = owner_id
                return i
        return None

    def write_slot(self, slot_idx: int, owner_id: str, data: bytes) -> bool:
        """Write data to an owned slot."""
        if slot_idx not in self._slot_owners:
            return False
        if self._slot_owners[slot_idx] != owner_id:
            return False
        if len(data) > self.SLOT_SIZE:
            return False
        offset = slot_idx * self.SLOT_SIZE
        self._pool[offset:offset + len(data)] = data
        return True

    def read_slot(self, slot_idx: int, owner_id: str) -> Optional[bytes]:
        """Read data from an owned slot."""
        if slot_idx not in self._slot_owners:
            return None
        if self._slot_owners[slot_idx] != owner_id:
            return None
        offset = slot_idx * self.SLOT_SIZE
        return bytes(self._pool[offset:offset + self.SLOT_SIZE])

    def release_slot(self, slot_idx: int, owner_id: str) -> bool:
        """Release a slot back to the pool."""
        if slot_idx not in self._slot_owners:
            return False
        if self._slot_owners[slot_idx] != owner_id:
            return False
        offset = slot_idx * self.SLOT_SIZE
        self._pool[offset:offset + self.SLOT_SIZE] = b'\x00' * self.SLOT_SIZE
        del self._slot_owners[slot_idx]
        return True


class MessageProtocol:
    """Binary protocol handler with integrity verification."""

    # Message format: [type:1][flags:1][seq:2][slot_ref:2][length:2][payload:N][mac:32]
    HEADER_SIZE = 8
    MAC_SIZE = 32
    MSG_TYPE_DATA = 0x01
    MSG_TYPE_READ = 0x02
    MSG_TYPE_BATCH_READ = 0x03

    def __init__(self, pool: SecureBufferPool, session_key: bytes):
        self._pool = pool
        self._session_key = session_key
        self._seq_counter = 0
        self._max_seq = 0xFFFF

    def _verify_mac(self, message: bytes) -> bool:
        """Verify message authentication code."""
        if len(message) < self.HEADER_SIZE + self.MAC_SIZE:
            return False
        payload = message[:-self.MAC_SIZE]
        received_mac = message[-self.MAC_SIZE:]
        expected_mac = hmac.new(self._session_key, payload, hashlib.sha256).digest()
        return hmac.compare_digest(received_mac, expected_mac)

    def _parse_header(self, data: bytes) -> Tuple[int, int, int, int, int]:
        """Parse message header fields."""
        msg_type = data[0]
        flags = data[1]
        seq = struct.unpack('>H', data[2:4])[0]
        slot_ref = struct.unpack('>h', data[4:6])[0]  # signed short for relative refs
        length = struct.unpack('>H', data[6:8])[0]
        return msg_type, flags, seq, slot_ref, length

    def _sanitize_slot_index(self, raw_ref: int, base_slot: int) -> int:
        """Convert a relative slot reference to an absolute index.

        Applies bitmask to ensure index stays within pool bounds.
        The mask 0x3F ensures values 0-63 (matching MAX_SLOTS).
        """
        absolute = base_slot + raw_ref
        # Apply bitmask to constrain to valid slot range
        return absolute & 0x3F

    def process_batch_read(self, message: bytes, owner_id: str, base_slot: int) -> List[bytes]:
        """Process a batch read request.

        Batch read allows reading multiple slots relative to a base slot.
        The slot_ref field in each entry is a signed offset from base_slot.
        """
        if not self._verify_mac(message):
            return []

        msg_type, flags, seq, primary_ref, length = self._parse_header(message)

        if msg_type != self.MSG_TYPE_BATCH_READ:
            return []

        if seq <= self._seq_counter and self._seq_counter != 0:
            return []  # replay protection
        self._seq_counter = seq

        # Parse batch entries from payload
        payload = message[self.HEADER_SIZE:self.HEADER_SIZE + length]
        if length % 2 != 0:
            return []  # each entry is 2 bytes (signed short)

        results = []
        entry_count = length // 2

        # Limit batch size to prevent DoS
        if entry_count > 16:
            return []

        for i in range(entry_count):
            # Each entry is a signed 16-bit relative offset
            rel_offset = struct.unpack('>h', payload[i*2:(i+1)*2])[0]

            # Sanitize the computed slot index
            slot_idx = self._sanitize_slot_index(rel_offset, base_slot)

            # Read from pool - ownership check provides access control
            data = self._pool.read_slot(slot_idx, owner_id)
            if data is not None:
                results.append(data)

        return results

    def process_message(self, message: bytes, owner_id: str, base_slot: int) -> Optional[bytes]:
        """Process a single read message."""
        if not self._verify_mac(message):
            return None

        msg_type, flags, seq, slot_ref, length = self._parse_header(message)

        if msg_type != self.MSG_TYPE_READ:
            return None

        if seq <= self._seq_counter and self._seq_counter != 0:
            return None
        self._seq_counter = seq

        slot_idx = self._sanitize_slot_index(slot_ref, base_slot)
        return self._pool.read_slot(slot_idx, owner_id)


class SessionManager:
    """Manages authenticated sessions with the buffer pool."""

    def __init__(self):
        self._pool = SecureBufferPool()
        self._sessions: Dict[str, dict] = {}

    def create_session(self, user_id: str) -> dict:
        """Create a new session with allocated slots."""
        session_key = os.urandom(32)
        session_id = hashlib.sha256(session_key + os.urandom(16)).hexdigest()[:16]

        # Allocate initial slots for this session
        slots = []
        for _ in range(4):
            slot = self._pool.allocate_slot(session_id)
            if slot is not None:
                slots.append(slot)

        if not slots:
            return None

        protocol = MessageProtocol(self._pool, session_key)

        session = {
            'id': session_id,
            'user_id': user_id,
            'key': session_key,
            'slots': slots,
            'base_slot': slots[0],
            'protocol': protocol,
            'created_at': time.time()
        }
        self._sessions[session_id] = session
        return session

    def handle_request(self, session_id: str, message: bytes) -> Optional[List[bytes]]:
        """Handle an incoming protocol message for a session."""
        if session_id not in self._sessions:
            return None

        session = self._sessions[session_id]

        # Session expiry check
        if time.time() - session['created_at'] > 3600:
            self._cleanup_session(session_id)
            return None

        protocol = session['protocol']
        base_slot = session['base_slot']
        owner_id = session['id']

        # Determine message type from first byte
        if len(message) < 1:
            return None

        if message[0] == MessageProtocol.MSG_TYPE_BATCH_READ:
            return protocol.process_batch_read(message, owner_id, base_slot)
        elif message[0] == MessageProtocol.MSG_TYPE_READ:
            result = protocol.process_message(message, owner_id, base_slot)
            return [result] if result else None

        return None

    def _cleanup_session(self, session_id: str):
        """Clean up session resources."""
        if session_id in self._sessions:
            session = self._sessions[session_id]
            for slot in session['slots']:
                self._pool.release_slot(slot, session['id'])
            del self._sessions[session_id]
